const num=v=>v===null||v===undefined||v===""||!Number.isFinite(Number(v))?null:Number(v);const gpus=n=>`${n} GPU${n===1?"":"s"}`;export function heldWords(inUse){const u=inUse||{};const serving=num(u.serving);const evals=num(u.eval);if(serving===null||evals===null)return null;return`serving ${serving}, evals ${evals}`+("build"in u?`, build checks ${num(u.build)??"unknown"}`:"")}export function waited(seconds){const s=num(seconds);if(s===null)return null;if(s>=3600)return`${(s/3600).toFixed(1).replace(/\.0$/,"")} h`;if(s>=120)return`${Math.round(s/60)} min`;return`${Math.max(0,Math.round(s))} s`}export const cardType=gpu=>String(gpu||"").split(":")[0].trim().toUpperCase();export function workerRobots(n,seats){return n!=null&&seats!=null?`${n} of ${seats}`:"—"}export function shortfallSentence(reason,details,{waiting:waiting=false}={}){const d=details||{};const pos=num(d.queue_position);const limitOf=num(d.queue_timeout_s);const queued=pos!==null?` You are number ${pos} in line${limitOf!==null?` and wait up to ${waited(limitOf)}`:""}.`:waiting?" Waiting robots start as soon as a slot frees up.":null;switch(reason){case"gpu_limit_reached":{const limit=num(d.limit);const serving=num(d.in_use&&d.in_use.serving);const evals=num(d.in_use&&d.in_use.eval);const checks=num(d.in_use&&d.in_use.build);const requested=num(d.requested);let out=limit!==null?`Your account's ${gpus(limit)} are all in use`:"Your account's GPUs are all in use";if(serving!==null&&evals!==null){out+=`: ${serving} serving, ${evals} on evals${checks?`, ${checks} on build checks`:""}`}out+=".";if(requested!==null)out+=` This needs ${gpus(requested)}.`;return out+(queued||(checks?" Stop a deployment, or wait for an eval or a build check to finish.":" Stop a deployment or wait for an eval to finish."))}case"gpu_busy":return`GPUs are busy right now.${queued||" Retry in a minute."}`;case"gpu_low_stock":{const type=cardType(d.gpu)||"This GPU type";const w=waited(d.waited_s);return w?`No ${type} came free in the ${w} its start waited. Try again in a minute.`:`${type} is out of stock right now. Try again in a minute.`}case"deployment_full":{const max=num(d.max_gpus);const head=max!==null?`This deployment holds all ${gpus(max)} it may (max_gpus).`:"This deployment holds all the GPUs it may (max_gpus).";return head+(queued||" Raise max_gpus, or wait for a robot to finish.")}case"queue_timeout":{const w=waited(d.waited_s);return`${w?`Waited ${w}`:"Waited"} for a free slot and none opened. Nothing is held. Try again shortly.`}default:return null}}export function shortfall(reason,details,opts){const tip=shortfallSentence(reason,details,opts);if(!tip)return null;const d=details||{};const limit=num(d.limit);const max=num(d.max_gpus);const type=cardType(d.gpu)||"GPU";const line={gpu_limit_reached:limit!==null?`All ${limit} account GPUs in use.`:"All account GPUs in use.",gpu_busy:"GPUs are busy right now.",gpu_low_stock:waited(d.waited_s)?`No ${type} came free in time.`:`No ${type} free right now.`,deployment_full:max!==null?`At its max of ${gpus(max)}.`:"At its max GPUs.",queue_timeout:"No slot opened in time."}[reason];return line?{line:line,tip:tip}:null}export function deathSentence(reason){switch(reason){case"gpu_out_of_memory":return"Out of GPU memory: the model copy did not fit on its card. Pick a card with more memory.";case"host_out_of_memory":return"Out of RAM: the worker used more memory than it had. Declare more with memory= on the policy.";case"crashed":return"The policy process kept crashing. Its logs say why.";case"hung":return"The policy kept hanging in infer: each copy was ended in a call past twice its time limit, so the worker "+"stopped. Its logs show the lines it printed before it hung.";case"group_member_lost":return"One machine of its group stopped, so the whole group stopped. The next connect starts a new group. "+"Its logs say which machine and why.";case"load_failed":return"Loading the policy raised while its worker started. Its logs show the error.";default:return null}}const WORKER_WHY={"cold-start":"Started for a robot that connected.","first-worker":"The machine its version's check ran on, kept on as its first worker.",resume:"Started again for a robot that reconnected.",min_workers:"Kept running: the policy's min workers.",warm_hours:"Kept running: the policy's warm hours.",buffer:"A spare, ready for the next robot (buffer workers).",replacement:"Started to take over from a worker that has served its hours.","version-replacement":"Started to serve a new version.","probe-alive":"Its robot's lease ran out while it still answered: kept a little longer.","idle-cooldown":"Stopped: no robot acted on it for the idle timeout.",unclaimed:"Stopped: no robot took it within a minute of starting. Billed until then.",surplus:"Stopped: a second worker was started for the same place. Not billed.","warm-hours-ended":"Stopped: its warm hours ended.","min-workers-lowered":"Stopped: the policy's min workers went down.","spare-unneeded":"Stopped: no robot needed it as a spare any more.","lease-expired":"Stopped: its robot stopped renewing its session.","version-retired":"Stopped: a newer version serves.","max-lifetime":"Stopped: it reached the longest a worker runs.",rotate:"Replaced after serving its hours.",rotated:"Replaced after serving its hours.","boot-timeout":"Stopped: it did not start in time.","gone-while-starting":"Ended while it was starting.",gone:"Ended by the platform.",interrupted:"Ended: its machine was taken away.",unhealthy:"Replaced: it stopped answering.","leak-reconcile":"Ended: no longer in use.",error:"Ended after an error.","resume-no-card":"Started new: its stopped worker could not start again, no card free where it was.","resume-failed":"Started new: its stopped worker could not start again.","stopped-expired":"Ended: kept stopped for a fast start, unused for the days one is kept.","stopped-surplus":"Ended: its version keeps one stopped worker for a fast start, the one used last."};export function workerReason(reason,state){const text=String(reason||"");const base=text.split(" (")[0];const cause=text.includes(" (")?text.slice(text.indexOf(" (")+2).replace(/\)$/,""):"";const death=deathSentence(cause)||deathSentence(base);const st=String(state||"").toLowerCase();const failed=st==="error"||st==="failed"||!!death;return{failed:failed,why:death||(text?WORKER_WHY[base]||null:null)}}export function deathWords(reason){const tip=deathSentence(reason);const line={gpu_out_of_memory:"out of GPU memory",host_out_of_memory:"out of RAM",crashed:"the policy kept crashing",hung:"policy hung in infer",group_member_lost:"a group machine stopped",load_failed:"the policy did not load"}[reason];return tip&&line?{line:line,tip:tip}:null}export function reasonSentence(reason,details){return shortfallSentence(reason,details)||deathSentence(reason)}export function evalWaitSentence(q){const cards=num(q&&q.cards);const need=cards!==null?gpus(cards):"its GPUs";const verb=cards===1?"is":"are";if(q&&q.reason==="gpu_limit_reached"){return`Your account's other deployments and evals hold its GPUs. This eval starts as soon as ${need} ${verb} free.`}if(q&&q.reason==="gpu_busy")return`GPUs are busy right now. This eval starts as soon as ${need} ${verb} free.`;return`${need.charAt(0).toUpperCase()}${need.slice(1)} ${verb} free now. It starts within a minute.`}export function evalTimeout(){return{line:"Failed: no GPU freed; nothing charged.",tip:"It waited for GPUs past its limit and none freed up. Run it again when fewer GPUs are in use."}}